def sum_distances(n, edges):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    par, order, seen = [-1] * n, [0], [False] * n
    seen[0] = True
    for v in order:
        for u in adj[v]:
            if not seen[u]:
                seen[u] = True
                par[u] = v
                order.append(u)
    size, down = [1] * n, [0] * n
    for v in reversed(order):
        if par[v] >= 0:
            size[par[v]] += size[v]
            down[par[v]] += down[v] + size[v]
    ans = [0] * n
    ans[0] = down[0]
    for v in order[1:]:
        ans[v] = ans[par[v]] - size[v] + (n - size[v])
    return ans

